function EvidenceArt({ scanning, shown }: { scanning: boolean; shown: boolean }) {
  return (
    <svg className="evidence-art" viewBox="0 0 600 330" role="img" aria-label="An inspection table moves an example document under a source-finding head">
      <g dangerouslySetInnerHTML={{ __html: base }} />
      <g className={scanning ? 'evidence-tray evidence-tray-scanning' : 'evidence-tray'} style={scanning ? undefined : { transform: shown ? 'translate(60.882px, 33.808px)' : 'translate(0px, 0px)' }}>
        <g dangerouslySetInnerHTML={{ __html: tray }} />
        <path className={scanning ? 'evidence-highlight evidence-highlight-scanning' : shown ? 'evidence-highlight visible' : 'evidence-highlight'} d={highlight} />
      </g>
    </svg>
  );
}

export function ScaleFigure({ phase }: { phase: 'classify' | 'plan' | 'suggest' }) {
  const figureRef = useRef<HTMLElement>(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const element = figureRef.current;
    if (!element) return;
    const observer = new IntersectionObserver((entries) => setVisible(entries[entries.length - 1].isIntersecting));
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  const position = phase === 'classify' ? -1 : phase === 'plan' ? 0 : 1;
  return <figure ref={figureRef} className="reader-figure scale-figure" data-visible={visible} aria-hidden="true">
    <svg className="evidence-art" viewBox="0 0 400 220">
      <g dangerouslySetInnerHTML={{ __html: scaleGeometry.fixed }} />
      <g className="scale-carriage" style={{ transform: `translate(${position * scaleGeometry.axis[0]}px, ${position * scaleGeometry.axis[1]}px)` }}>
        <g className="scale-inspection" dangerouslySetInnerHTML={{ __html: scaleGeometry.carriage }} />
      </g>
    </svg>
  </figure>;
}

export function ExtractionFigure({ scanning = true }: { progress: string; scanning?: boolean }) {
  const figureRef = useRef<HTMLElement>(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const element = figureRef.current;
    if (!element) return;
    const observer = new IntersectionObserver((entries) => setVisible(entries[entries.length - 1].isIntersecting));
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return (
    <figure ref={figureRef} className="reader-figure" data-active={scanning && visible} aria-hidden="true">
      <svg viewBox="0 0 160 130">
        <ellipse cx="80" cy="117" rx="68" ry="8" fill="#d8d1c3" />
        <path d="M15 93 L82 63 L147 94 L80 125 Z" fill="#bdb7ac" stroke="#111" strokeWidth="2" />
        <path d="M15 93 L80 122 L80 126 L15 98 Z M80 122 L147 94 L147 99 L80 126 Z" fill="#8f897e" stroke="#111" strokeWidth="2" />
        <path d="M54 75 L75 65 L75 99 L54 108 Z M75 65 L99 75 L99 108 L75 99 Z" fill="#fffefa" stroke="#111" strokeWidth="2" />
        <path d="M58 79 L70 74 M58 84 L70 79 M58 89 L70 84 M80 74 L94 80 M80 79 L94 85 M80 84 L94 90" stroke="#888" strokeWidth="1.5" />
        <path className="reader-highlight" d="M57 79 L71 73" stroke="#ffd84d" strokeWidth="4" />
        <path d="M47 54 L33 63 L43 86 L52 82 L46 68 L57 65 M104 54 L119 63 L109 86 L100 82 L106 68 L95 65" fill="#aaa69e" stroke="#111" strokeWidth="2" />
        <path d="M53 52 L78 41 L105 52 L105 77 L79 88 L53 76 Z" fill="#e9e4d9" stroke="#111" strokeWidth="2" />
        <path d="M53 52 L79 64 L105 52 M79 64 L79 88" fill="none" stroke="#111" strokeWidth="2" />
        <g className="reader-arm">
          <path d="M97 61 L111 72 L98 83 L83 78 L78 79 L82 83 L98 88 L117 74 L104 58 Z" fill="#aaa69e" stroke="#111" strokeWidth="2" />
          <circle cx="100" cy="61" r="3" fill="#eeeae1" stroke="#111" />
          <circle cx="111" cy="73" r="2" fill="#eeeae1" stroke="#111" />
          <path d="M83 78 L68 78 L68 81 L83 83 Z" fill="#eeeae1" stroke="#111" strokeWidth="1.5" />
        </g>
        <g className="reader-head">
          <path d="M48 23 L78 10 L110 24 L110 49 L79 63 L48 49 Z" fill="#eeeae1" stroke="#111" strokeWidth="2" />
          <path d="M48 23 L79 37 L110 24 M79 37 L79 63" fill="none" stroke="#111" strokeWidth="2" />
          <path d="M54 29 L74 38 L74 50 L54 41 Z" fill="#282827" stroke="#111" strokeWidth="1.5" />
          <g className="reader-eyes" fill="#ffd84d"><circle cx="60" cy="37" r="2" /><circle cx="69" cy="41" r="2" /></g>
          <path d="M84 40 L104 31 M84 45 L104 36 M84 50 L98 44" stroke="#999" strokeWidth="1" />
        </g>
        <g fill="#444"><circle cx="23" cy="94" r="1.4"/><circle cx="81" cy="119" r="1.4"/><circle cx="139" cy="95" r="1.4"/><circle cx="43" cy="67" r="2"/><circle cx="113" cy="67" r="2"/><circle cx="62" cy="57" r="1.4"/><circle cx="95" cy="57" r="1.4"/></g>
      </svg>
    </figure>
  );
}

export default function EvidenceFigure() {
  const [shown, setShown] = useState(false);
  return (
    <figure className="evidence-figure">
      <div className="evidence-figure-header"><strong>Trace a finding</strong><span>Illustrative example</span></div>
      <EvidenceArt scanning={false} shown={shown} />
      <div className="evidence-figure-footer">
        <button type="button" className="secondary evidence-button" onClick={() => setShown(!shown)}>{shown ? 'Reset example' : 'Show source'}</button>
        <span role="status" aria-live="polite">{shown ? 'PAGE 04 · SOURCE REGION' : 'SELECT A FINDING'}</span>
      </div>
    </figure>
  );
}
